CREATE TABLE IF NOT EXISTS reference.software_release(sw_release TEXT PRIMARY KEY,release_sequence INT UNIQUE,release_date DATE,vehicle_model TEXT,sw_variant TEXT,release_type TEXT,baseline_release BOOLEAN DEFAULT FALSE,notes TEXT); CREATE TABLE IF NOT EXISTS reference.ecu_relationship(relationship_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,source_ecu TEXT,target_ecu TEXT,interaction_type TEXT,network TEXT,direction TEXT DEFAULT 'Bidirectional',criticality TEXT DEFAULT 'Medium',approved_by TEXT,metadata JSONB DEFAULT '{}'::jsonb); CREATE TABLE IF NOT EXISTS reference.ecu_owner(ecu_name TEXT PRIMARY KEY,department TEXT,team_name TEXT,owner_name TEXT,contact_email TEXT,escalation_path TEXT,active BOOLEAN DEFAULT TRUE);
